    size_t fn=bo.low_nn.size()+bo.low_nr.size()+bo.low_nl.size()+bo.high_nn.size()+bo.high_nrnl.size();double oldm=double(f32.bytes()+r32.bytes())/double(1<<20),newm=double(f18.bytes()+r18.bytes())/double(1<<20);std::cout<<"orbit-closure-packed18-plan OK W="<<TARGET_W<<" checked="<<checked<<" old_attach_mib="<<oldm<<" packed_sidecar_mib="<<newm<<" sidecar_ratio="<<(oldm?newm/oldm:0.0)<<" forward_bytes_per_orbit=1 reverse_bytes_per_orbit=1.25 reverse_jblock_bits_embedded=6 direct_forward_match=1 avoided_forward_attach_bytes="<<(fn*sizeof(uint32_t))<<"\n";return 0;
